      children: (0,jsx_runtime.jsx)(_components.code, {
        className: "language-mermaid",
        children: "flowchart TD\n    A[GATE CS Strategy] --> B[Understand Paper]\n    A --> C[Subject Prioritization]\n    A --> D[Practice PYQs]\n    A --> E[Mock Tests]\n    A --> F[Revision Cycle]\n    B --> B1[100 marks, 65 Qs]\n    B --> B2[1-mark & 2-mark]\n    B --> B3[Negative Marking]\n    C --> C1[High Weight: DSA, OS, CN, COA]\n    C --> C2[Medium: DBMS, TOC, CD]\n    C --> C3[Low: Digital Logic, Aptitude]\n    D --> D1[2010-2025: 1000+ Qs]\n    D --> D2[Subject-wise PYQ practice]\n    E --> E1[Weekly mock tests]\n    E --> E2[Analyze mistakes]\n    F --> F1[Daily: 30 min revision]\n    F --> F2[Weekly: full subject review]\n"
      })
